#include <memory>
#include <iostream>

class Resource { public: int data = 42; ~Resource() { std::cout << "Destroyed\n"; } };

void consume(std::auto_ptr<Resource> p) {
    // p now owns the resource
    std::cout << "Consumed: " << p->data << "\n";
}

int main() {
    std::auto_ptr<Resource> owner(new Resource());

    // Assignment transfers ownership (owner becomes null)
    std::auto_ptr<Resource> receiver = owner;

    if (owner.get() == nullptr) {
        std::cout << "Owner relinquished ownership.\n";
    }

    // If 'owner' were used here, it would be UB/crash.
    // Calling consume() also transfers ownership, deleting the resource upon return.
}
